-- ADR-0048 d.2 (I16.1): brief_templates is the single home for what a brief CONTAINS.
--
-- The agency's brief system is a real, bilingual 8-brief deck
-- (the agency brief-template deck, client-supplied, not included), and the app already encoded its list: the
-- wizard's BRIEF_TYPES *is* those eight. What was missing was the fields. This seeds them,
-- transcribed from the deck INCLUDING its guidance lines — those are the model's prompt as
-- much as the human's hint (d.2), so paraphrasing them changes generated output.
--
-- Tenant data, not code, for two reasons the ADR records: the deck's wording will change and
-- a redeploy should not be how it changes; and the four types Edward asked for
-- (creative_strategy, communications_strategy, brand_guidelines, custom) are not in the deck
-- and had to be authored — drafted in docs/reference/brief-templates-additional.md, and
-- **the Arabic in those four is a first draft awaiting a native speaker** (tracker I16.2).
--
-- Read by anyone in the tenant: the wizard needs the field list to render a brief at all.
-- Written only by organization:manage — the same authority that edits roles and offices.

create table brief_templates (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null references tenants(id),
  brief_type  text not null,
  -- Ordered. [{key, en, ar, guidance, multiline}] — the array's order IS the form's order,
  -- which is why this is jsonb and not a child table: nobody reorders a brief by dragging
  -- rows in a join table, and a template is edited as one document or not at all.
  fields      jsonb not null default '[]'::jsonb,
  is_active   boolean not null default true,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  constraint uq_brief_templates_tenant_type unique (tenant_id, brief_type),
  constraint chk_brief_templates_fields_array check (jsonb_typeof(fields) = 'array')
);

create index idx_brief_templates_tenant_id on brief_templates (tenant_id);

comment on table brief_templates is
  'ADR-0048 d.2: what each brief type contains. Ordered field list with EN/AR labels and the '
  'deck''s own guidance text. Tenant data so the wording changes without a release.';
comment on column brief_templates.fields is
  'Ordered [{key, en, ar, guidance, multiline}]. Order is the form order. A template with an '
  'empty array makes its brief type UNSELECTABLE in the wizard (ADR-0048 d.2) - deliberately, '
  'because a type that silently generates an empty brief looks broken.';

alter table brief_templates enable row level security;
alter table brief_templates force row level security;

-- Everyone in the tenant reads: without the field list the wizard cannot render a brief.
create policy brief_templates_tenant_select on brief_templates
  for select using (tenant_id = app.current_tenant_id());

create policy brief_templates_manage_insert on brief_templates
  for insert with check (
    tenant_id = app.current_tenant_id() and app.has_permission('organization', 'manage')
  );

create policy brief_templates_manage_update on brief_templates
  for update using (
    tenant_id = app.current_tenant_id() and app.has_permission('organization', 'manage')
  ) with check (
    tenant_id = app.current_tenant_id() and app.has_permission('organization', 'manage')
  );

create policy brief_templates_manage_delete on brief_templates
  for delete using (
    tenant_id = app.current_tenant_id() and app.has_permission('organization', 'manage')
  );

create trigger set_updated_at before update on brief_templates
  for each row execute function app.set_updated_at();

-- ---------------------------------------------------------------- the seed ----

