    ('brand_guidelines', '[{"key": "background", "en": "Background", "ar": "الخلفية", "guidance": "New brand, a refresh, or documenting what already exists? What triggered this?", "multiline": true}, {"key": "scope", "en": "Scope", "ar": "النطاق", "guidance": "Which assets are in scope — logo, colour, typography, imagery, voice, applications? Name what is out of scope too.", "multiline": true}, {"key": "existingAssets", "en": "Existing Assets & Their State", "ar": "الأصول الحالية وحالتها", "guidance": "What exists today, where it lives, and what condition it is in. Be honest about gaps.", "multiline": true}, {"key": "brandFoundation", "en": "Brand Foundation", "ar": "أساس العلامة", "guidance": "Purpose, values, personality — or where they are already written down.", "multiline": true}, {"key": "toneOfVoice", "en": "Tone of Voice", "ar": "نبرة الصوت", "guidance": "How do we sound? Three adjectives, plus what we never sound like.", "multiline": true}, {"key": "languages", "en": "Languages & Scripts", "ar": "اللغات والخطوط", "guidance": "Arabic and English treatment, bilingual lockups, which script leads.", "multiline": true}, {"key": "applications", "en": "Applications Required", "ar": "التطبيقات المطلوبة", "guidance": "Everywhere the guidelines must work: signage, social, packaging, OOH, digital, print.", "multiline": true}, {"key": "dosDonts", "en": "Do''s & Don''ts to Capture", "ar": "المسموح والممنوع", "guidance": "Misuses already seen in the wild are the most valuable entries here.", "multiline": true}, {"key": "references", "en": "References & Inspiration", "ar": "المراجع والإلهام", "guidance": "Guidelines from other brands worth learning from, and why.", "multiline": true}, {"key": "deliverableFormat", "en": "Deliverable Format", "ar": "صيغة التسليم", "guidance": "PDF, editable source, web? Roughly how many pages, and who has to be able to open it?", "multiline": true}, {"key": "custodian", "en": "Approval & Custodian", "ar": "الاعتماد وأمين العلامة", "guidance": "Who signs it off, and who owns keeping it true afterwards.", "multiline": true}]'::jsonb),
    ('single_execution', '[{"key": "deliverableType", "en": "Deliverable Type", "ar": "نوع المخرج", "guidance": "2D design, 3D, copy, video edit, or other.", "multiline": true}, {"key": "task", "en": "The Task", "ar": "المهمة", "guidance": "Describe exactly what''s needed: message, visual, content. One task per brief.", "multiline": true}, {"key": "reference", "en": "Reference / KV", "ar": "مرجع بصري أو التصميم الأساسي", "guidance": "The key visual or reference this follows, or a link to it.", "multiline": true}, {"key": "specs", "en": "Specs", "ar": "المواصفات", "guidance": "Size(s), format, platform, language(s), file type.", "multiline": true}, {"key": "copy", "en": "Copy / Message", "ar": "النص أو الرسالة", "guidance": "Exact copy if final, or direction if we''re writing it.", "multiline": true}, {"key": "restrictions", "en": "Restrictions", "ar": "القيود", "guidance": "Brand rules, don''ts, legal, sensitivities.", "multiline": true}]'::jsonb),
    ('custom', '[{"key": "background", "en": "Background", "ar": "الخلفية", "guidance": "Where are we today, and what triggered this brief?", "multiline": true}, {"key": "task", "en": "The Task", "ar": "المهمة", "guidance": "One sentence. What must this work achieve?", "multiline": true}, {"key": "audience", "en": "Audience", "ar": "الجمهور", "guidance": "Who is this for? Mindset, not just demographics.", "multiline": true}, {"key": "deliverables", "en": "Deliverables", "ar": "المخرجات", "guidance": "Every item we must hand over, with versions and sizes where they matter.", "multiline": true}, {"key": "mandatories", "en": "Mandatories & Restrictions", "ar": "الإلزاميات والقيود", "guidance": "Non-negotiables, restrictions, no-go zones.", "multiline": true}, {"key": "successMeasures", "en": "How We Will Know It Worked", "ar": "مقاييس النجاح", "guidance": "How success is judged. Be specific.", "multiline": true}]'::jsonb)
  ) as t(brief_type, fields)
  -- Idempotent, and deliberately NOT an upsert: once a tenant has edited a template, a
  -- later migration re-running this must not overwrite their wording with the deck's.
  on conflict (tenant_id, brief_type) do nothing;
end $$;

comment on function app.seed_tenant_brief_templates(uuid) is
  'ADR-0048 d.2: seed the brief field sets for a tenant, transcribed from the Lantern deck plus '
  'the four types Edward asked for. Idempotent and non-destructive - it never overwrites an '
  'edited template.';

select app.seed_tenant_brief_templates(id) from tenants;

-- Future tenants: fold into the provisioning wrapper the bootstrap path already calls, the
-- same way disciplines were folded in by 20260816090000. Thin passthrough; nothing else changes.
create or replace function public.seed_tenant_roles(p_tenant uuid) returns void
language sql
set search_path = public, app, extensions as $$
  select app.seed_tenant_roles(p_tenant);
  select app.seed_tenant_disciplines(p_tenant);
  select app.seed_tenant_brief_templates(p_tenant);
$$;
revoke execute on function public.seed_tenant_roles(uuid) from public, anon, authenticated;
grant execute on function public.seed_tenant_roles(uuid) to service_role;
